            "text": "1. **RFID** ใช้คลื่นความถี่วิทยุในการอ่านรหัสจากแท็กโดยไม่ต้องมองเห็นป้ายโดยตรง อ่านผ่านวัสดุบังสายตาได้ และอ่านหลายชิ้นพร้อมกันได้ด้วยกลไก **Anti-collision**\n2. **โครงสร้างด้านในของแท็ก RFID** ประกอบด้วย **ไมโครชิป (IC)** ทำหน้าที่เก็บข้อมูลและประมวลผลสัญญาณ เชื่อมต่อกับ **สายอากาศ (Antenna)** ที่ทำหน้าที่รับพลังงานคลื่นและส่งสัญญาณตอบกลับ\n3. **แท็กแบบพาสซีฟ (Passive Tag)** ไม่มีแบตเตอรี่ แต่อาศัยพลังงานจากเครื่องอ่าน โดยย่าน LF/HF ใช้การเหนี่ยวนำสนามแม่เหล็ก (**Inductive Coupling**) ส่วนย่าน UHF ใช้การสะท้อนคลื่นกลับ (**Backscatter**)\n4. **การเลือกย่านความถี่** ต้องดูหน้างานและวัสดุเป็นหลัก ย่าน **LF (125/134.2 kHz)** ทะลุน้ำและเนื้อเยื่อได้ดีเหมาะกับสัตว์ ย่าน **HF (13.56 MHz)** เหมาะกับบัตรแตะระยะใกล้และใช้ร่วมกับ **NFC** ได้ ส่วนย่าน **UHF (860–960 MHz)** อ่านได้ไกลหลายเมตรเหมาะกับคลังสินค้าแต่แพ้โลหะและของเหลว\n5. **การตรวจคุณภาพข้อมูล** ต้องระวัง 3 อาการสำคัญ คือ **อ่านขาด (Missed Read)**, **อ่านเกิน (Stray Read)** และ **อ่านซ้ำ (Duplicate Read)** โดยต้องตรวจสอบเทียบกับใบส่งของแบบรายรหัสเสมอ ห้ามดูเพียงยอดรวมจำนวนชิ้น"
